import React, { useEffect, useMemo, useState } from 'react';
import {
  Button,
  FormActions,
  Input,
  Modal,
  MoneyInput,
  Select,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import type {
  CreateScenarioCostItemDto,
  CreateScenarioDto,
  ScenarioResultDto,
} from '../../../services/fpc/types';
import { resolveApiErrorMessage } from '../../../services/catalogUiSchemaService';
import styles from './ScenarioForm.module.css';

const TEST_ID = 'sensitivity-assumptions-form';

function defaultPeriod(): { start: string; end: string } {
  const y = new Date().getFullYear();
  return { start: `${y}-01-01`, end: `${y}-12-31` };
}

function toIsoDate(ymd: string, endOfDay = false): string {
  if (!ymd) return new Date().toISOString();
  return endOfDay ? `${ymd}T23:59:59.000Z` : `${ymd}T00:00:00.000Z`;
}

export type SensitivityAssumptionsFormModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSaved: () => void;
  scenarios: ScenarioResultDto[];
};

type FormState = {
  mode: 'new' | 'run-existing';
  existingId: string;
  name: string;
  periodStart: string;
  periodEnd: string;
  totalBudget: number;
  rent: number;
  salary: number;
  inventory: number;
  ar: number;
};

type FormErrors = Partial<Record<'name' | 'periodStart' | 'periodEnd' | 'existingId', string>>;

function emptyForm(scenarios: ScenarioResultDto[]): FormState {
  const p = defaultPeriod();
  const draft = scenarios.find(s => (s.status || '').toLowerCase() === 'draft');
  const any = scenarios[0];
  return {
    mode: scenarios.length > 0 ? 'run-existing' : 'new',
    existingId: draft?.id ?? any?.id ?? '',
    name: 'Cơ sở — biến nhạy cảm',
    periodStart: p.start,
    periodEnd: p.end,
    totalBudget: 0,
    rent: 0,
    salary: 0,
    inventory: 0,
    ar: 0,
  };
}

function buildCostItems(form: FormState): CreateScenarioCostItemDto[] {
  const rows: CreateScenarioCostItemDto[] = [];
  if (form.rent > 0) {
    rows.push({ costCode: 'RENT', costCodeName: 'Tiền thuê mặt bằng', amount: form.rent });
  }
  if (form.salary > 0) {
    rows.push({ costCode: 'SALARY', costCodeName: 'Lương nhân viên', amount: form.salary });
  }
  if (form.inventory > 0) {
    rows.push({ costCode: 'INV', costCodeName: 'Tồn kho', amount: form.inventory });
  }
  if (form.ar > 0) {
    rows.push({ costCode: 'AR', costCodeName: 'Công nợ phải thu', amount: form.ar });
  }
  return rows;
}

/**
 * Form cấu hình biến nhạy cảm (Kind G + Modal).
 * - Tạo kịch bản Base kèm cost drivers rồi Run → BE ghi sensitivity lattice.
 * - Hoặc Run lại kịch bản đã có (không sửa cost — BE chưa có Update scenario).
 */
const SensitivityAssumptionsFormModal: React.FC<SensitivityAssumptionsFormModalProps> = ({
  isOpen,
  onClose,
  onSaved,
  scenarios,
}) => {
  const dispatch = useAppDispatch();
  const [form, setForm] = useState<FormState>(() => emptyForm(scenarios));
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitting, setSubmitting] = useState(false);

  const scenarioOptions = useMemo(
    () => scenarios.map(s => ({
      value: s.id,
      label: `${s.name || s.scenarioType} · ${s.status}${s.sensitivity?.rows?.length ? ' · có ma trận' : ''}`,
    })),
    [scenarios],
  );

  useEffect(() => {
    if (!isOpen) return;
    setForm(emptyForm(scenarios));
    setErrors({});
    setSubmitting(false);
  }, [isOpen, scenarios]);

  const setField = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    setForm(f => ({ ...f, [key]: value }));
    if (key in { name: 1, periodStart: 1, periodEnd: 1, existingId: 1 }) {
      setErrors(e => ({ ...e, [key]: undefined }));
    }
  };

  const validate = (): boolean => {
    const next: FormErrors = {};
    if (form.mode === 'run-existing') {
      if (!form.existingId) next.existingId = 'Chọn kịch bản để chạy';
    } else {
      if (!form.name.trim()) next.name = 'Nhập tên kịch bản';
      if (!form.periodStart) next.periodStart = 'Chọn từ ngày';
      if (!form.periodEnd) next.periodEnd = 'Chọn đến ngày';
      if (form.periodStart && form.periodEnd && form.periodEnd < form.periodStart) {
        next.periodEnd = 'Đến ngày phải ≥ Từ ngày';
      }
    }
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSubmit = async () => {
    if (!validate()) return;
    setSubmitting(true);
    try {
      if (form.mode === 'run-existing') {
        await fpcService.runScenario(form.existingId);
        dispatchAppToast(dispatch, {
          message: 'Đã chạy kịch bản — ma trận nhạy cảm đã cập nhật',
          type: 'success',
        });
      } else {
        const costItems = buildCostItems(form);
        const costSum = costItems.reduce((s, c) => s + c.amount, 0);
        const dto: CreateScenarioDto = {
          name: form.name.trim(),
          scenarioType: 'Base',
          periodStart: toIsoDate(form.periodStart),
          periodEnd: toIsoDate(form.periodEnd, true),
          totalBudget: form.totalBudget > 0 ? form.totalBudget : (costSum > 0 ? costSum : undefined),
          summary: 'Tạo từ form biến nhạy cảm',
          costItems: costItems.length ? costItems : undefined,
        };
        const created = await fpcService.createScenario(dto);
        await fpcService.runScenario(created.id);
        dispatchAppToast(dispatch, {
          message: 'Đã tạo Base và tính ma trận nhạy cảm',
          type: 'success',
        });
      }
      onSaved();
      onClose();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: resolveApiErrorMessage(err, 'Lỗi khi tính biến nhạy cảm'),
        type: 'error',
      });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Cấu hình biến nhạy cảm"
      size="lg"
      data-testid={`${TEST_ID}-modal`}
    >
      <div className={styles.formBody} data-testid={`${TEST_ID}-body`}>
        <p className={styles.lead}>
          Ma trận -30% / -10% / Base / +10% / +20% do BE tính sau khi Chạy kịch bản.
          Nhập khoản mục chi phí (thuê · lương · tồn · công nợ) khi tạo mới để lattice đầy đủ.
        </p>

        <div className={styles.modeRow}>
          <label className={styles.radioLabel}>
            <input
              type="radio"
              name="sens-mode"
              checked={form.mode === 'new'}
              onChange={() => setField('mode', 'new')}
              data-testid={`${TEST_ID}-mode-new`}
            />
            Tạo kịch bản Base mới rồi chạy
          </label>
          <label className={styles.radioLabel}>
            <input
              type="radio"
              name="sens-mode"
              checked={form.mode === 'run-existing'}
              onChange={() => setField('mode', 'run-existing')}
              disabled={scenarios.length === 0}
              data-testid={`${TEST_ID}-mode-existing`}
            />
            Chạy lại kịch bản đã có
          </label>
        </div>

        {form.mode === 'run-existing' ? (
          <div className={styles.formGrid}>
            <div className={styles.fullWidth}>
              <Select
                label="Kịch bản"
                required
                value={form.existingId}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setField('existingId', e.target.value)}
                options={[{ value: '', label: '— Chọn —' }, ...scenarioOptions]}
                error={errors.existingId}
                data-testid={`${TEST_ID}-scenario`}
              />
            </div>
            <p className={`${styles.lead} ${styles.fullWidth}`}>
              BE chưa hỗ trợ sửa cost trên kịch bản cũ — Run dùng dữ liệu hiện có (plan kỳ + cost đã lưu).
            </p>
          </div>
        ) : (
          <>
            <div className={styles.formGrid}>
              <Input
                label="Tên kịch bản"
                required
                value={form.name}
                onChange={e => setField('name', e.target.value)}
                error={errors.name}
                data-testid={`${TEST_ID}-name`}
              />
              <Input
                label="Loại"
                value="Base"
                readOnly
                data-testid={`${TEST_ID}-type-ro`}
              />
              <Input
                label="Từ ngày"
                type="date"
                required
                value={form.periodStart}
                onChange={e => setField('periodStart', e.target.value)}
                error={errors.periodStart}
                data-testid={`${TEST_ID}-from`}
              />
              <Input
                label="Đến ngày"
                type="date"
                required
                value={form.periodEnd}
                onChange={e => setField('periodEnd', e.target.value)}
                error={errors.periodEnd}
                data-testid={`${TEST_ID}-to`}
              />
              <div className={styles.fullWidth}>
                <MoneyInput
                  label="Tổng ngân sách dự chi"
                  value={form.totalBudget}
                  onChange={v => setField('totalBudget', Number(v) || 0)}
                  data-testid={`${TEST_ID}-budget`}
                />
              </div>
            </div>
            <div className={styles.sectionHint}>Biến chi phí cơ sở (6 dòng lattice sau Run)</div>
            <div className={styles.formGrid}>
              <MoneyInput
                label="Tiền thuê mặt bằng"
                value={form.rent}
                onChange={v => setField('rent', Number(v) || 0)}
                data-testid={`${TEST_ID}-rent`}
              />
              <MoneyInput
                label="Lương nhân viên"
                value={form.salary}
                onChange={v => setField('salary', Number(v) || 0)}
                data-testid={`${TEST_ID}-salary`}
              />
              <MoneyInput
                label="Tồn kho"
                value={form.inventory}
                onChange={v => setField('inventory', Number(v) || 0)}
                data-testid={`${TEST_ID}-inventory`}
              />
              <MoneyInput
                label="Công nợ phải thu"
                value={form.ar}
                onChange={v => setField('ar', Number(v) || 0)}
                data-testid={`${TEST_ID}-ar`}
              />
            </div>
          </>
        )}

        <FormActions align="end" className={styles.formActions}>
          <Button variant="secondary" onClick={onClose} disabled={submitting} data-testid={`${TEST_ID}-cancel`}>
            Hủy
          </Button>
          <Button
            variant="primary"
            onClick={() => void handleSubmit()}
            disabled={submitting}
            data-testid={`${TEST_ID}-submit`}
          >
            {submitting ? 'Đang xử lý…' : form.mode === 'new' ? 'Tạo Base và tính ma trận' : 'Chạy và cập nhật ma trận'}
          </Button>
        </FormActions>
      </div>
    </Modal>
  );
};

export default SensitivityAssumptionsFormModal;
