import React, { useEffect, useState } from 'react';
import {
  Button,
  FormActions,
  Input,
  Modal,
  MoneyInput,
  Select,
  TextArea,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import type { CreateScenarioCostItemDto, CreateScenarioDto } from '../../../services/fpc/types';
import { resolveApiErrorMessage } from '../../../services/catalogUiSchemaService';
import styles from './ScenarioForm.module.css';

const TEST_ID = 'create-scenario-form';

export const SCENARIO_TYPE_OPTIONS = [
  { value: 'Base', label: 'Cơ sở (Base)' },
  { value: 'Conservative', label: 'Thận trọng (Downside)' },
  { value: 'Upside', label: 'Tăng trưởng (Upside)' },
];

function defaultPeriod(): { start: string; end: string } {
  const now = new Date();
  const y = now.getFullYear();
  const start = `${y}-01-01`;
  const end = `${y}-12-31`;
  return { start, end };
}

function toIsoDate(ymd: string, endOfDay = false): string {
  if (!ymd) return new Date().toISOString();
  return endOfDay ? `${ymd}T23:59:59.000Z` : `${ymd}T00:00:00.000Z`;
}

export type CreateScenarioFormModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSaved: () => void;
};

type FormState = {
  name: string;
  scenarioType: string;
  periodStart: string;
  periodEnd: string;
  totalBudget: number;
  summary: string;
  rent: number;
  salary: number;
  inventory: number;
  ar: number;
};

type FormErrors = Partial<Record<'name' | 'scenarioType' | 'periodStart' | 'periodEnd', string>>;

function emptyForm(): FormState {
  const p = defaultPeriod();
  return {
    name: '',
    scenarioType: 'Base',
    periodStart: p.start,
    periodEnd: p.end,
    totalBudget: 0,
    summary: '',
    rent: 0,
    salary: 0,
    inventory: 0,
    ar: 0,
  };
}

function buildCostItems(form: FormState): CreateScenarioCostItemDto[] {
  const rows: CreateScenarioCostItemDto[] = [];
  if (form.rent > 0) {
    rows.push({ costCode: 'RENT', costCodeName: 'Tiền thuê mặt bằng', amount: form.rent });
  }
  if (form.salary > 0) {
    rows.push({ costCode: 'SALARY', costCodeName: 'Lương nhân viên', amount: form.salary });
  }
  if (form.inventory > 0) {
    rows.push({ costCode: 'INV', costCodeName: 'Tồn kho', amount: form.inventory });
  }
  if (form.ar > 0) {
    rows.push({ costCode: 'AR', costCodeName: 'Công nợ phải thu', amount: form.ar });
  }
  return rows;
}

const CreateScenarioFormModal: React.FC<CreateScenarioFormModalProps> = ({
  isOpen,
  onClose,
  onSaved,
}) => {
  const dispatch = useAppDispatch();
  const [form, setForm] = useState<FormState>(emptyForm);
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (!isOpen) return;
    setForm(emptyForm());
    setErrors({});
    setSubmitting(false);
  }, [isOpen]);

  const setField = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    setForm(f => ({ ...f, [key]: value }));
    if (key === 'name' || key === 'scenarioType' || key === 'periodStart' || key === 'periodEnd') {
      setErrors(e => ({ ...e, [key]: undefined }));
    }
  };

  const validate = (): boolean => {
    const next: FormErrors = {};
    if (!form.name.trim()) next.name = 'Nhập tên kịch bản';
    if (!form.scenarioType) next.scenarioType = 'Chọn loại kịch bản';
    if (!form.periodStart) next.periodStart = 'Chọn từ ngày';
    if (!form.periodEnd) next.periodEnd = 'Chọn đến ngày';
    if (form.periodStart && form.periodEnd && form.periodEnd < form.periodStart) {
      next.periodEnd = 'Đến ngày phải ≥ Từ ngày';
    }
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const buildDto = (): CreateScenarioDto => {
    const costItems = buildCostItems(form);
    const costSum = costItems.reduce((s, c) => s + c.amount, 0);
    return {
      name: form.name.trim(),
      scenarioType: form.scenarioType,
      periodStart: toIsoDate(form.periodStart),
      periodEnd: toIsoDate(form.periodEnd, true),
      totalBudget: form.totalBudget > 0 ? form.totalBudget : (costSum > 0 ? costSum : undefined),
      summary: form.summary.trim() || undefined,
      costItems: costItems.length ? costItems : undefined,
    };
  };

  const handleSave = async (andRun: boolean) => {
    if (!validate()) return;
    setSubmitting(true);
    try {
      const created = await fpcService.createScenario(buildDto());
      if (andRun) {
        await fpcService.runScenario(created.id);
        dispatchAppToast(dispatch, {
          message: 'Đã tạo và chạy kịch bản',
          type: 'success',
        });
      } else {
        dispatchAppToast(dispatch, { message: 'Đã tạo kịch bản (nháp)', type: 'success' });
      }
      onSaved();
      onClose();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: resolveApiErrorMessage(err, 'Lỗi khi lưu kịch bản'),
        type: 'error',
      });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Tạo kịch bản"
      size="lg"
      data-testid={`${TEST_ID}-modal`}
    >
      <div className={styles.formBody} data-testid={`${TEST_ID}-body`}>
        <div className={styles.formGrid}>
          <Input
            label="Tên kịch bản"
            required
            value={form.name}
            onChange={e => setField('name', e.target.value)}
            error={errors.name}
            placeholder="VD: Cơ sở 2026"
            data-testid={`${TEST_ID}-name`}
          />
          <Select
            label="Loại kịch bản"
            required
            value={form.scenarioType}
            onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setField('scenarioType', e.target.value)}
            options={SCENARIO_TYPE_OPTIONS}
            error={errors.scenarioType}
            data-testid={`${TEST_ID}-type`}
          />
          <Input
            label="Từ ngày"
            type="date"
            required
            value={form.periodStart}
            onChange={e => setField('periodStart', e.target.value)}
            error={errors.periodStart}
            data-testid={`${TEST_ID}-from`}
          />
          <Input
            label="Đến ngày"
            type="date"
            required
            value={form.periodEnd}
            onChange={e => setField('periodEnd', e.target.value)}
            error={errors.periodEnd}
            data-testid={`${TEST_ID}-to`}
          />
          <div className={styles.fullWidth}>
            <MoneyInput
              label="Tổng ngân sách dự chi"
              value={form.totalBudget}
              onChange={v => setField('totalBudget', Number(v) || 0)}
              data-testid={`${TEST_ID}-budget`}
            />
          </div>
          <div className={styles.fullWidth}>
            <TextArea
              label="Tóm tắt"
              value={form.summary}
              onChange={e => setField('summary', e.target.value)}
              rows={2}
              placeholder="Ghi chú giả định (tuỳ chọn)"
              data-testid={`${TEST_ID}-summary`}
            />
          </div>
        </div>

        <div className={styles.sectionHint}>
          Khoản mục chi phí (tuỳ chọn) — dùng cho ma trận biến nhạy cảm sau khi chạy
        </div>
        <div className={styles.formGrid}>
          <MoneyInput
            label="Tiền thuê mặt bằng"
            value={form.rent}
            onChange={v => setField('rent', Number(v) || 0)}
            data-testid={`${TEST_ID}-rent`}
          />
          <MoneyInput
            label="Lương nhân viên"
            value={form.salary}
            onChange={v => setField('salary', Number(v) || 0)}
            data-testid={`${TEST_ID}-salary`}
          />
          <MoneyInput
            label="Tồn kho"
            value={form.inventory}
            onChange={v => setField('inventory', Number(v) || 0)}
            data-testid={`${TEST_ID}-inventory`}
          />
          <MoneyInput
            label="Công nợ phải thu"
            value={form.ar}
            onChange={v => setField('ar', Number(v) || 0)}
            data-testid={`${TEST_ID}-ar`}
          />
        </div>

        <FormActions align="end" className={styles.formActions}>
          <Button variant="secondary" onClick={onClose} disabled={submitting} data-testid={`${TEST_ID}-cancel`}>
            Hủy
          </Button>
          <Button
            variant="secondary"
            onClick={() => void handleSave(false)}
            disabled={submitting}
            data-testid={`${TEST_ID}-save-draft`}
          >
            Lưu nháp
          </Button>
          <Button
            variant="primary"
            onClick={() => void handleSave(true)}
            disabled={submitting}
            data-testid={`${TEST_ID}-save-run`}
          >
            {submitting ? 'Đang lưu…' : 'Lưu và chạy'}
          </Button>
        </FormActions>
      </div>
    </Modal>
  );
};

export default CreateScenarioFormModal;
