import React, { useCallback, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Button,
  FormActions,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { Spin, Text, Title, Popconfirm } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import type {
  ExpansionSimulationDto,
  ScenarioResultDto,
  ScenarioSensitivityDto,
} from '../../../services/fpc/types';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import { resolveApiErrorMessage } from '../../../services/catalogUiSchemaService';
import CreateScenarioFormModal from './CreateScenarioFormModal';
import SensitivityAssumptionsFormModal from './SensitivityAssumptionsFormModal';
import styles from './ScenarioManagerPage.module.css';

const TEST_ID = 'scenario-manager';

const fCompact = (v: number): string => {
  const abs = Math.abs(v);
  const sign = v < 0 ? '-' : '';
  if (abs >= 1_000_000_000) return `${sign}${(abs / 1_000_000_000).toFixed(1)} tỷ`;
  if (abs >= 1_000_000) return `${sign}${(abs / 1_000_000).toFixed(0)} tr`;
  if (abs >= 1_000) return `${sign}${(abs / 1_000).toFixed(0)} ng`;
  return `${v.toLocaleString('vi-VN')}`;
};

const formatSensitivityCell = (unit: string, value: number): string => {
  if (unit === 'percent') return `${value.toLocaleString('vi-VN', { maximumFractionDigits: 1 })}%`;
  if (unit === 'days') return `${Math.round(value)} ngày`;
  return fCompact(value);
};

const moneyShockClass = (colPct: number): string | undefined => {
  if (colPct <= -30) return styles.statusRed;
  if (colPct < 0) return styles.statusYellow;
  if (colPct === 0) return styles.statusGreen;
  return styles.statusGreen;
};

/** Ưu tiên Base Completed có sensitivity · else Completed bất kỳ có sensitivity. */
function pickSensitivity(scenarios: ScenarioResultDto[]): ScenarioSensitivityDto | null {
  const completed = scenarios.filter(s => (s.status || '').toLowerCase() === 'completed');
  const withSens = (list: ScenarioResultDto[]) =>
    list.find(s => s.sensitivity?.rows && s.sensitivity.rows.length > 0)?.sensitivity ?? null;
  const base = completed.filter(s => (s.scenarioType || '').toLowerCase() === 'base');
  return withSens(base) ?? withSens(completed) ?? withSens(scenarios);
}

function scenarioCardClass(type: string): string {
  const t = (type || '').toLowerCase();
  if (t.includes('conserv') || t.includes('down') || t.includes('thận')) return styles.scenarioDownside;
  if (t.includes('up') || t.includes('growth') || t.includes('tăng')) return styles.scenarioUpside;
  return styles.scenarioBase;
}

function scenarioTitleColor(type: string): string {
  const t = (type || '').toLowerCase();
  if (t.includes('conserv') || t.includes('down') || t.includes('thận')) return '#ef4444';
  if (t.includes('up') || t.includes('growth') || t.includes('tăng')) return '#2563eb';
  return '#059669';
}

function expansionInvestmentTotal(e: ExpansionSimulationDto): number {
  if (e.totalInvestment != null && Number.isFinite(e.totalInvestment)) return e.totalInvestment;
  return (e.capexFitOut ?? 0)
    + (e.capexEquipment ?? 0)
    + (e.preOpeningCost ?? 0)
    + (e.workingCapitalRequired ?? 0)
    + (e.initialInventoryValue ?? 0);
}

function pickPrimaryExpansion(list: ExpansionSimulationDto[]): ExpansionSimulationDto | undefined {
  if (!list.length) return undefined;
  const completed = list.find(x => (x.status || '').toLowerCase() === 'completed');
  return completed ?? list[0];
}

const ScenarioManagerPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const {
    canViewScenarios,
    canManageScenarios,
    canViewExpansionSimulator,
    canRunExpansionSimulator,
    canExportReports,
  } = useFpcPermissions();

  const [scenarios, setScenarios] = useState<ScenarioResultDto[]>([]);
  const [expansions, setExpansions] = useState<ExpansionSimulationDto[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [sensitivityOpen, setSensitivityOpen] = useState(false);
  const [runningId, setRunningId] = useState<string | null>(null);

  const loadAll = useCallback(async () => {
    setLoading(true);
    setLoadError(false);
    try {
      const [scList, exList] = await Promise.all([
        fpcService.getScenarioList(),
        canViewExpansionSimulator
          ? fpcService.getExpansionSimList().catch(() => [] as ExpansionSimulationDto[])
          : Promise.resolve([] as ExpansionSimulationDto[]),
      ]);
      setScenarios(Array.isArray(scList) ? scList : []);
      setExpansions(Array.isArray(exList) ? exList : []);
    } catch {
      setScenarios([]);
      setExpansions([]);
      setLoadError(true);
      dispatchAppToast(dispatch, {
        message: 'Không thể tải kịch bản',
        type: 'error',
      });
    } finally {
      setLoading(false);
    }
  }, [canViewExpansionSimulator, dispatch]);

  useEffect(() => {
    const t = window.setTimeout(() => {
      void loadAll();
    }, 0);
    return () => window.clearTimeout(t);
  }, [loadAll]);

  const handleRunScenario = async (id: string) => {
    setRunningId(id);
    try {
      await fpcService.runScenario(id);
      dispatchAppToast(dispatch, { message: 'Đã chạy kịch bản', type: 'success' });
      await loadAll();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: resolveApiErrorMessage(err, 'Lỗi khi chạy kịch bản'),
        type: 'error',
      });
    } finally {
      setRunningId(null);
    }
  };

  const handleDeleteScenario = async (id: string) => {
    try {
      await fpcService.deleteScenario(id);
      dispatchAppToast(dispatch, { message: 'Đã xóa kịch bản', type: 'success' });
      await loadAll();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: resolveApiErrorMessage(err, 'Lỗi khi xóa kịch bản'),
        type: 'error',
      });
    }
  };

  if (!canViewScenarios) {
    return (
      <div className={styles.page} data-testid={`${TEST_ID}-page`}>
        <div className={styles.empty}>
          <Text type="secondary">Bạn không có quyền xem kịch bản.</Text>
        </div>
      </div>
    );
  }

  const expansion = pickPrimaryExpansion(expansions);
  const sensitivity = pickSensitivity(scenarios);

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <div className={styles.headerCard}>
        <div className={styles.headerTop}>
          <div>
            <Title level={4}>
              <i className="fas fa-cubes" style={{ marginRight: 8, color: '#2563eb' }} />
              Kịch bản và mở rộng
            </Title>
            <Text type="secondary">So sánh kịch bản đã lưu · mô phỏng mở điểm (real API)</Text>
          </div>
          <FormActions align="end">
            <Button onClick={() => void loadAll()} data-testid={`${TEST_ID}-refresh-btn`}>
              <i className="fas fa-redo" /> Làm mới
            </Button>
            {canManageScenarios && (
              <Button
                variant="primary"
                onClick={() => setCreateOpen(true)}
                data-testid={`${TEST_ID}-create-scenario-btn`}
              >
                <i className="fas fa-plus" /> Tạo kịch bản
              </Button>
            )}
            {canViewExpansionSimulator && (
              <Button
                variant="secondary"
                onClick={() => navigate('/tc/kh/mo-rong-ch')}
                data-testid={`${TEST_ID}-expansion-list-btn`}
              >
                <i className="fas fa-store" /> Mở rộng CH
              </Button>
            )}
            {canRunExpansionSimulator && (
              <Button
                variant="secondary"
                onClick={() => navigate('/tc/kh/mo-rong-ch/new')}
                data-testid={`${TEST_ID}-expansion-create-btn`}
              >
                <i className="fas fa-plus" /> Tạo mô phỏng mở rộng
              </Button>
            )}
            {canExportReports && (
              <Button
                variant="secondary"
                disabled={scenarios.length === 0}
                onClick={() => window.print()}
                data-testid={`${TEST_ID}-export-btn`}
              >
                <i className="fas fa-print" /> In
              </Button>
            )}
          </FormActions>
        </div>
      </div>

      {loading && (
        <div className={styles.loading} data-testid={`${TEST_ID}-loading`}>
          <Spin />
          <Text type="secondary">Đang tải kịch bản…</Text>
        </div>
      )}

      {!loading && loadError && (
        <div className={styles.empty} data-testid={`${TEST_ID}-error`}>
          <Text type="secondary">Không tải được dữ liệu. Thử Làm mới.</Text>
          <Button variant="primary" onClick={() => void loadAll()}>Thử lại</Button>
        </div>
      )}

      {!loading && !loadError && (
        <div className={styles.contentPanel} data-testid={`${TEST_ID}-content`}>
          <div className={styles.sectionCard}>
            <div className={styles.sectionHeader}>
              <h3 className={styles.sectionTitle}>So sánh kịch bản</h3>
              <span className={styles.sectionBadge}>{scenarios.length} kịch bản</span>
            </div>
            {scenarios.length === 0 ? (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                <Text type="secondary">
                  Chưa có kịch bản đã lưu. Tạo Base / Thận trọng / Tăng trưởng rồi chạy để so sánh.
                </Text>
                {canManageScenarios && (
                  <div>
                    <Button
                      variant="primary"
                      onClick={() => setCreateOpen(true)}
                      data-testid={`${TEST_ID}-empty-create`}
                    >
                      <i className="fas fa-plus" /> Tạo kịch bản
                    </Button>
                  </div>
                )}
              </div>
            ) : (
              <div className={styles.grid3}>
                {scenarios.map(s => {
                  const color = scenarioTitleColor(s.scenarioType);
                  const status = (s.status || '').toLowerCase();
                  return (
                    <div
                      key={s.id}
                      className={`${styles.scenarioCard} ${scenarioCardClass(s.scenarioType)}`}
                      data-testid={`${TEST_ID}-card-${s.id}`}
                    >
                      <h4 style={{ color, margin: 0 }}>{s.name || s.scenarioType}</h4>
                      <p style={{ color, margin: '8px 0 0', fontSize: 22, fontWeight: 700 }}>
                        {fCompact(s.projectedRevenue ?? 0)}
                      </p>
                      <div className={styles.scenarioLabel}>Doanh thu dự kiến</div>
                      <p style={{ fontSize: 16, color, margin: '8px 0 0' }}>
                        {fCompact(s.projectedEbitda ?? 0)}
                      </p>
                      <div className={styles.scenarioLabel}>Lợi nhuận trước khấu hao</div>
                      <p style={{ fontSize: 16, margin: '8px 0 0' }}>
                        {fCompact(s.projectedCashBalance ?? 0)}
                      </p>
                      <div className={styles.scenarioLabel}>Tiền cuối kỳ</div>
                      {(s.fundingRequired ?? 0) > 0 && (
                        <p style={{ fontSize: 14, color: '#ef4444', margin: '8px 0 0', fontWeight: 700 }}>
                          Cần bổ sung: {fCompact(s.fundingRequired ?? 0)}
                        </p>
                      )}
                      {s.status && (
                        <div className={styles.scenarioLabel} style={{ marginTop: 8 }}>
                          Trạng thái: {s.status} · {s.scenarioType}
                        </div>
                      )}
                      {canManageScenarios && (
                        <div style={{ display: 'flex', gap: 8, marginTop: 12, flexWrap: 'wrap' }}>
                          <Button
                            variant="secondary"
                            disabled={runningId === s.id || status === 'running'}
                            onClick={() => void handleRunScenario(s.id)}
                            data-testid={`${TEST_ID}-run-${s.id}`}
                          >
                            {runningId === s.id ? 'Đang chạy…' : 'Chạy'}
                          </Button>
                          <Popconfirm
                            title="Xóa kịch bản này?"
                            onConfirm={() => void handleDeleteScenario(s.id)}
                          >
                            <Button variant="secondary" data-testid={`${TEST_ID}-delete-${s.id}`}>
                              Xóa
                            </Button>
                          </Popconfirm>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          <div className={styles.sectionCard} data-testid={`${TEST_ID}-sensitivity`}>
            <div className={styles.sectionHeader}>
              <h3 className={styles.sectionTitle}>Biến nhạy cảm</h3>
              <span className={styles.sectionBadge}>
                {sensitivity
                  ? `${sensitivity.rows.length} biến · ${sensitivity.sourceScenarioName || 'kịch bản đã run'}`
                  : 'Từ kịch bản đã run'}
              </span>
            </div>
            {!sensitivity ? (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                <Text type="secondary" data-testid={`${TEST_ID}-sensitivity-empty`}>
                  Chưa có ma trận nhạy cảm từ API — tạo/chạy kịch bản Base (có khoản mục chi phí) để BE tính lattice.
                  Không dùng số mô phỏng.
                </Text>
                {canManageScenarios && (
                  <div>
                    <Button
                      variant="primary"
                      onClick={() => setSensitivityOpen(true)}
                      data-testid={`${TEST_ID}-sensitivity-config-btn`}
                    >
                      <i className="fas fa-sliders-h" /> Cấu hình biến nhạy cảm
                    </Button>
                  </div>
                )}
              </div>
            ) : (
              <>
                {canManageScenarios && (
                  <div style={{ marginBottom: 12 }}>
                    <Button
                      variant="secondary"
                      onClick={() => setSensitivityOpen(true)}
                      data-testid={`${TEST_ID}-sensitivity-reconfig-btn`}
                    >
                      <i className="fas fa-sliders-h" /> Cấu hình / chạy lại
                    </Button>
                  </div>
                )}
                <div className={styles.tableWrapper}>
                  <table className={styles.table} data-testid={`${TEST_ID}-sensitivity-table`}>
                    <thead>
                      <tr>
                        <th>Biến</th>
                        {sensitivity.columns.map(col => (
                          <th key={col} className={styles.colCenter}>
                            {col === 0 ? 'Base' : `${col > 0 ? '+' : ''}${col}%`}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {sensitivity.rows.map(row => (
                        <tr key={row.code} data-testid={`${TEST_ID}-sensitivity-row-${row.code}`}>
                          <td style={{ fontWeight: 500 }}>{row.label}</td>
                          {row.values.map((val, idx) => {
                            const col = sensitivity.columns[idx] ?? 0;
                            const tone = row.unit === 'money' ? moneyShockClass(col) : undefined;
                            const isBase = col === 0;
                            return (
                              <td key={`${row.code}-${col}`} className={styles.colCenter}>
                                {tone ? (
                                  <span className={tone} style={{ padding: '2px 8px', borderRadius: 6 }}>
                                    {isBase ? <strong>{formatSensitivityCell(row.unit, val)}</strong>
                                      : formatSensitivityCell(row.unit, val)}
                                  </span>
                                ) : isBase ? (
                                  <strong>{formatSensitivityCell(row.unit, val)}</strong>
                                ) : (
                                  formatSensitivityCell(row.unit, val)
                                )}
                              </td>
                            );
                          })}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </>
            )}
          </div>

          {canViewExpansionSimulator && (
            <div className={styles.sectionCard} data-testid={`${TEST_ID}-expansion`}>
              <div className={styles.sectionHeader}>
                <h3 className={styles.sectionTitle}>Mô phỏng mở điểm mới</h3>
                <span className={styles.sectionBadge}>{expansions.length} chứng từ · real API</span>
              </div>
              {!expansion ? (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  <Text type="secondary">Chưa có mô phỏng mở rộng.</Text>
                  {canRunExpansionSimulator && (
                    <Button
                      variant="primary"
                      onClick={() => navigate('/tc/kh/mo-rong-ch/new')}
                      data-testid={`${TEST_ID}-expansion-empty-create`}
                    >
                      <i className="fas fa-plus" /> Tạo chứng từ mở rộng
                    </Button>
                  )}
                </div>
              ) : (
                <>
                  <Text type="secondary" style={{ display: 'block', marginBottom: 8 }}>
                    KPI từ «{expansion.name || '—'}» ({expansion.status || 'Draft'})
                    {(expansion.status || '').toLowerCase() !== 'completed'
                      ? ' — chưa chạy: hòa vốn/khuyến nghị trống đến khi Chạy mô phỏng'
                      : ''}
                  </Text>
                  <div className={styles.statsRow}>
                    <div className={styles.statCard}>
                      <span className={styles.statLabel}>Vốn đầu tư</span>
                      <span className={styles.statValue}>
                        {fCompact(expansionInvestmentTotal(expansion))}
                      </span>
                    </div>
                    <div className={styles.statCard}>
                      <span className={styles.statLabel}>Thời gian hòa vốn</span>
                      <span className={`${styles.statValue} ${styles.positive}`}>
                        {expansion.breakEvenMonth != null ? `${expansion.breakEvenMonth} tháng` : '—'}
                      </span>
                    </div>
                    <div className={styles.statCard}>
                      <span className={styles.statLabel}>Thời gian hoàn vốn</span>
                      <span className={`${styles.statValue} ${styles.positive}`}>
                        {expansion.paybackMonths != null ? `${expansion.paybackMonths} tháng` : '—'}
                      </span>
                    </div>
                    <div className={styles.statCard}>
                      <span className={styles.statLabel}>Số ngày an toàn sau khi mở</span>
                      <span className={`${styles.statValue} ${styles.warning}`}>
                        {expansion.runwayImpactMonths != null
                          ? `${Math.round(expansion.runwayImpactMonths * 30)} ngày`
                          : '—'}
                      </span>
                    </div>
                  </div>
                  {expansion.recommendation && (
                    <div style={{ padding: '8px 0', fontSize: 14, display: 'flex', alignItems: 'center', gap: 8 }}>
                      <i className="fas fa-lightbulb" style={{ color: '#f59e0b' }} />
                      <span><strong>Khuyến nghị:</strong> {expansion.recommendation}</span>
                    </div>
                  )}
                  <div className={styles.tableWrapper} style={{ marginTop: 12 }}>
                    <table className={styles.table} data-testid={`${TEST_ID}-expansion-table`}>
                      <thead>
                        <tr>
                          <th>Tên</th>
                          <th>Trạng thái</th>
                          <th>Tổng đầu tư</th>
                          <th>Hòa vốn</th>
                          <th>DT thuần/tháng</th>
                          <th>Khuyến nghị</th>
                          <th />
                        </tr>
                      </thead>
                      <tbody>
                        {expansions.map(row => (
                          <tr
                            key={row.id}
                            data-testid={`${TEST_ID}-expansion-row-${row.id}`}
                            className={row.id === expansion.id ? styles.tableTotalRow : undefined}
                          >
                            <td style={{ fontWeight: 500 }}>{row.name || '—'}</td>
                            <td>{row.status || '—'}</td>
                            <td style={{ textAlign: 'right' }}>{fCompact(expansionInvestmentTotal(row))}</td>
                            <td style={{ textAlign: 'center' }}>
                              {row.breakEvenMonth != null ? `${row.breakEvenMonth} tháng` : '—'}
                            </td>
                            <td style={{ textAlign: 'right' }}>
                              {row.monthlyNetCashflow != null ? fCompact(row.monthlyNetCashflow) : '—'}
                            </td>
                            <td>{row.recommendation || '—'}</td>
                            <td>
                              <Button
                                variant="secondary"
                                onClick={() => navigate(`/tc/kh/mo-rong-ch/${row.id}`)}
                                data-testid={`${TEST_ID}-expansion-open-${row.id}`}
                              >
                                Xem
                              </Button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </>
              )}
            </div>
          )}
        </div>
      )}

      <CreateScenarioFormModal
        isOpen={createOpen}
        onClose={() => setCreateOpen(false)}
        onSaved={() => void loadAll()}
      />
      <SensitivityAssumptionsFormModal
        isOpen={sensitivityOpen}
        onClose={() => setSensitivityOpen(false)}
        onSaved={() => void loadAll()}
        scenarios={scenarios}
      />
    </div>
  );
};

export default ScenarioManagerPage;
